import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";
import { useNavigate } from "react-router-dom";
import Popup from "./Popup";
import Button from "react-bootstrap/Button";
import axios from "axios";
import { Group } from "../Model/Group.model";
import AddIcon from "@mui/icons-material/Add";
import DeleteIcon from "@mui/icons-material/Delete";
import "./Groups.scss";

function Groups() {
  const navigate = useNavigate();
  const [groups, setGroups] = useState<Group[]>([]);
  const [showPopup, setShowPopup] = useState<boolean>(false);

  useEffect(() => {
    axios
      .get<Group[]>(`http://localhost:5257/api/Group/`)
      .then((response) => {
        setGroups(response.data);
        console.log(response.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const openGroup = (event: any, groupId: string) => {
    event?.stopPropagation();
    navigate(`/group/${groupId}`);
  };
  const handleOpenPopup = () => {
    setShowPopup(true);
  };

  const handleClosePopup = () => {
    setShowPopup(false);
  };

  const onCreate = (value: string) => {
    axios
      .post<Group>("http://localhost:5257/api/Group", { name: value })
      .then((response) => {
        setGroups((old) => [...old, response.data]);
      })
      .catch((error) => {
        alert("Name cannot be empty");
      });
  };

  const checkHandler = (idToUpdate: string, checked: boolean) => {
    const group = groups.find((x) => x.id === idToUpdate);
    if (group != null) {
      setGroups((group) =>
        group.map((x) =>
          x.id === idToUpdate ? { ...x, isChecked: !checked } : x
        )
      );
    }
  };
  return (
    <div className="container">
      <div className="bg-white  d-flex mt-2 justify-content-between align-items-center p-2">
        <div>
          <input type="checkbox" className="form-check-input me-2" />
          Select all
        </div>
        <div>
          <button className="btn btn-outline-danger btn-sm me-2">
            Delete Selected
          </button>
        </div>
      </div>
      <div className="d-flex align-items-start bg-white">
        <input
          type="checkbox"
          name=""
          className="form-check-input me-3 mt-1"
          id=""
        />
        <div>
          <div className="fw-semibold">Group</div>
          <div className="small text-muted">
            24 members •<span className="text-danger">Owe: $2,450</span> •
            <span className="text-success">Owed: $3,800</span> • Created on June
            12, 2025
          </div>
        </div>
      </div>
    </div>
  );
}

export default Groups;
